import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React, { useMemo } from "react";
import { GOLD_BACKGROUND_STYLING } from "../gacha_styling";
import type { CasinoStateWithUI } from "../types";
import { GACHA_QUERY_KEYS } from "../useGachaQueryParam";
import { useHintUnlockState } from "../useHintUnlockState";
import { GachaProgressBarInline } from "./GachaProgressBar";

type GachaBannerSelectorProps = {
  selectedBanner: string;
  onBannerChange: (bannerSlug: string) => void;
  state: CasinoStateWithUI;
  auxControl?: React.ReactNode;
  className?: string;
};

export default function GachaBannerSelector({
  selectedBanner,
  onBannerChange,
  state,
  auxControl,
  className,
}: GachaBannerSelectorProps) {
  const selectedBannerData = state.banners.find(
    (b) => b.slug === selectedBanner,
  );
  const progress = state.banner_progress?.find(
    (bp) => bp.banner_slug === selectedBanner,
  );
  const hintHref = selectedBanner
    ? `/rounds/fates_thread_casino/hints?${GACHA_QUERY_KEYS.BANNER}=${encodeURIComponent(selectedBanner)}`
    : undefined;
  const bannerHintsUnlockedAt = useMemo(
    () =>
      selectedBanner
        ? state.banner_hints_unlocked_at?.[selectedBanner]
        : undefined,
    [selectedBanner, state.banner_hints_unlocked_at],
  );
  const hintsUnlocked = useHintUnlockState(bannerHintsUnlockedAt);
  const hintAvailableAt = useMemo(() => {
    if (!bannerHintsUnlockedAt) {
      return undefined;
    }
    return new Date(bannerHintsUnlockedAt).toLocaleString("en-US");
  }, [bannerHintsUnlockedAt]);
  let hintTooltip: string | undefined;
  if (bannerHintsUnlockedAt) {
    if (hintsUnlocked) {
      hintTooltip = "Ask for a hint";
    } else {
      hintTooltip = `Hints will be available for this banner at ${hintAvailableAt}`;
    }
  } else {
    hintTooltip = undefined;
  }
  const hint =
    bannerHintsUnlockedAt && hintHref
      ? {
          href: hintHref,
          disabled: !hintsUnlocked,
          tooltip: hintTooltip,
        }
      : undefined;

  return (
    <div
      className={cn(
        "w-full flex flex-row items-center gap-4 px-6 py-4 rounded-lg max-w-5xl",
        GOLD_BACKGROUND_STYLING,
        className,
      )}
    >
      <div className="flex gap-2 items-center">
        <span className="text-xl text-black font-bold">Banner:</span>
        <Select value={selectedBanner} onValueChange={onBannerChange}>
          <SelectTrigger
            id="banner-select"
            className="w-48 bg-[#A47E0C5C] border-[#6F5300] text-black font-semibold rounded-lg"
            chevronClassName="text-[#6F5300]"
          >
            <SelectValue>{selectedBannerData?.name}</SelectValue>
          </SelectTrigger>
          <SelectContent className="w-48 bg-[#CEA946] text-black border-[#6F5300]">
            {state.banners
              .filter((banner) => banner.state === "unlocked")
              .map((banner) => (
                <SelectItem
                  key={banner.slug}
                  value={banner.slug}
                  className="focus:bg-cash-dark-brown focus:text-white hover:bg-cash-dark-brown hover:text-white cursor-pointer"
                >
                  {banner.name}
                </SelectItem>
              ))}
          </SelectContent>
        </Select>
      </div>
      {auxControl && <div className="flex-shrink-0">{auxControl}</div>}
      {progress && (
        <div className="ml-auto">
          <GachaProgressBarInline
            num_clues_pulled={progress.num_clues_pulled}
            total_clues={progress.total_clues}
            hint={hint}
          />
        </div>
      )}
    </div>
  );
}
