import { ConditionalTooltip } from "@hunt/shadcn";
import { cn } from "@hunt/styled-ui";
import React from "react";
import { HintBadge, HintBadgeCompact } from "../../../../components/HintBadge";
import ClueCorner from "../assets/clue_corner.svg";
import ClueCornerWithHint from "../assets/clue_corner_with_hint.svg";

const HINT_BADGE_STYLING = "w-[104px] h-[46px]";

type HintBadgeConfig = {
  href: string;
  disabled?: boolean;
  tooltip?: React.ReactNode;
};

type GachaProgressBarProps = {
  num_clues_pulled: number;
  total_clues: number;
};
function GachaProgressBar({
  num_clues_pulled,
  total_clues,
}: GachaProgressBarProps) {
  const safeTotalClues = Math.max(total_clues, 0);
  const safeNumCluesPulled = Math.min(
    Math.max(num_clues_pulled, 0),
    safeTotalClues,
  );
  const progressPercentage =
    safeTotalClues > 0 ? (safeNumCluesPulled / safeTotalClues) * 100 : 0;

  return (
    <div className="w-full flex flex-col items-end justify-center gap-1">
      <span className="text-black text-2xl italic">
        {safeNumCluesPulled}/{safeTotalClues} Clues
      </span>
      <div className="w-full bg-gray-300 rounded-full h-4 border border-gray-500 overflow-hidden">
        <div
          className="h-full bg-green-600 transition-all duration-300 ease-out"
          style={{ width: `${progressPercentage}%` }}
          role="progressbar"
          aria-valuenow={safeNumCluesPulled}
          aria-valuemin={0}
          aria-valuemax={safeTotalClues}
        />
      </div>
    </div>
  );
}

type GachaProgressBarInBannerProps = GachaProgressBarProps & {
  hint?: HintBadgeConfig;
};
export function GachaProgressBarInBanner({
  num_clues_pulled,
  total_clues,
  hint,
}: GachaProgressBarInBannerProps) {
  return (
    <div className="relative w-80">
      <img
        src={hint ? ClueCornerWithHint : ClueCorner}
        alt=""
        aria-hidden="true"
        className="absolute -bottom-px -right-px z-10 transform-gpu drop-shadow-[-4px_-4px_4px_rgba(0,0,0,0.25)] select-none"
      />

      <div
        className={cn(
          "relative flex flex-col items-end justify-center z-20 p-4 pl-14 gap-2",
          hint && "pb-3",
        )}
      >
        {hint ? (
          <ConditionalTooltip tooltip={hint.tooltip}>
            <HintBadge
              href={hint.href}
              disabled={hint.disabled}
              aria-label="Hints for the current banner"
              className={HINT_BADGE_STYLING}
            />
          </ConditionalTooltip>
        ) : null}
        <GachaProgressBar
          num_clues_pulled={num_clues_pulled}
          total_clues={total_clues}
        />
      </div>
    </div>
  );
}

type GachaProgressBarInlineProps = GachaProgressBarProps & {
  hint?: HintBadgeConfig;
};
export function GachaProgressBarInline({
  num_clues_pulled,
  total_clues,
  hint,
}: GachaProgressBarInlineProps) {
  return (
    <div className="flex items-center gap-4">
      <div className="w-64">
        <GachaProgressBar
          num_clues_pulled={num_clues_pulled}
          total_clues={total_clues}
        />
      </div>
      {hint ? (
        <>
          <ConditionalTooltip tooltip={hint.tooltip}>
            <HintBadgeCompact
              href={hint.href}
              disabled={hint.disabled}
              aria-label="Hints for the current banner"
              className="flex lg:hidden"
            />
          </ConditionalTooltip>
          <ConditionalTooltip tooltip={hint.tooltip}>
            <HintBadge
              href={hint.href}
              disabled={hint.disabled}
              aria-label="Hints for the current banner"
              className={cn(HINT_BADGE_STYLING, "hidden lg:flex")}
            />
          </ConditionalTooltip>
        </>
      ) : null}
    </div>
  );
}
